Problem:
A popular coffee shop has coffee and cappuccinos. Each coffee requires 8 units of milk and 2 units of water. Each cappuccino requires 7 units of cream and 4 units of water. The coffee shop purchases a total of 3300 units of milk and 2600 units of cream. Regulars like the coffee and at least thirty percent of drinks must be coffee. However, cappuccinos make more profit, and the owner wants to sell more cappuccino than coffee. Since the town is in a water shortage, how many of each drink should be made to minimize the total amount of water needed?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "coffee drinks",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "cappuccino drinks",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "coffee drinks",
     "coef": 2.0
    },
    {
     "var": "cappuccino drinks",
     "coef": 4.0
    }
   ]
  },
  "constraints": [
   {
    "name": "milk",
    "terms": [
     {
      "var": "coffee drinks",
      "coef": 8.0
     }
    ],
    "sense": "<=",
    "rhs": 3300.0
   },
   {
    "name": "cream",
    "terms": [
     {
      "var": "cappuccino drinks",
      "coef": 7.0
     }
    ],
    "sense": "<=",
    "rhs": 2600.0
   },
   {
    "name": "at least 30% coffee",
    "terms": [
     {
      "var": "coffee drinks",
      "coef": 0.7
     },
     {
      "var": "cappuccino drinks",
      "coef": -0.3
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "more cappuccino than coffee",
    "terms": [
     {
      "var": "cappuccino drinks",
      "coef": 1.0
     },
     {
      "var": "coffee drinks",
      "coef": -1.0
     }
    ],
    "sense": ">=",
    "rhs": 1.0
   }
  ]
 },
 "facts": {
  "objective": 10.0,
  "values": {
   "coffee drinks": 1.0,
   "cappuccino drinks": 2.0
  },
  "binding": [
   "more cappuccino than coffee"
  ],
  "slack": {
   "milk": 3292.0,
   "cream": 2586.0,
   "at least 30% coffee": 0.1,
   "more cappuccino than coffee": 0.0
  },
  "shadow_prices": null
 }
}
